<script module lang="ts">
/**
 * A tool invocation shown as one expandable row (`design/components/tool-call.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tool-call.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import * as zag from '@zag-js/collapsible'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  agentMember,
  attributes,
  joinSlot,
  normalizeProps,
  useDirection,
  watchEffect,
  type IconRole,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/tool-call.module.css'
import CodeBlock from '../structure/CodeBlock.svelte'
import JsonTree from '../structure/JsonTree.svelte'

export type ToolCallStatus = 'pending' | 'running' | 'done' | 'error' | 'denied' | 'approval'

export interface ToolCallMessages {
  input: string
  output: string
  status: Record<ToolCallStatus, string>
}

export interface ToolCallProps {
  defaultOpen?: boolean
  /**
   * The duration, preformatted by the app, such as "1.2s".
   */
  duration?: string
  /**
   * The tool's mark, `tool` by default, or `terminal`, `network` or `document` when the app
   * knows the kind.
   */
  icon?: IconRole
  /**
   * The arguments, rendered as JsonTree for a value or as CodeBlock for a string.
   */
  input?: unknown
  /**
   * The app's text for a failure or a refusal.
   */
  message?: string
  /**
   * All of the card's text (generic English defaults), which localized hosts replace.
   */
  messages?: ToolCallMessages
  /**
   * The tool's name as the model called it, such as `read_file` or `search_web`.
   */
  name: string
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * The result, such as a CodeBlock, a JsonTree or a Markdown.
   */
  output?: Snippet
  status: 'error' | 'denied' | 'done' | 'pending' | 'running' | 'approval'
  /**
   * One line describing the call, such as the file read or the query run.
   */
  summary?: string
}
</script>

<script lang="ts">
let {
  defaultOpen = false,
  duration,
  icon = 'tool',
  input,
  message,
  messages = (() => ({
    input: 'Input',
    output: 'Output',
    status: {
      pending: 'Pending',
      running: 'Running',
      done: 'Done',
      error: 'Failed',
      denied: 'Denied',
      approval: 'Awaiting approval',
    },
  }))(),
  name,
  onOpenChange,
  open,
  output,
  status,
  summary,
}: ToolCallProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ name: name }))
const slots = {
  get output() {
    return output
  },
}
let trigger = $state<HTMLElement | null>(null)
const running = $derived(status === 'running')
const hasBody = $derived(input !== undefined || Boolean(slots.output) || message !== undefined)
const statusIcon = $derived(
  (
    {
      pending: 'time',
      running: 'loading',
      done: 'success',
      error: 'error',
      denied: 'denied',
      approval: 'help',
    } as const
  )[status],
)
const documentDirection = useDirection(() => trigger)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      defaultOpen: defaultOpen,
      disabled: !hasBody,
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ToolCall',
    element: () => trigger,
    state: () => ({ status: status, expanded: api.open }),
    actions: {
      expand: () =>
        (() => {
          if (!hasBody) throw new Error('The call has nothing to show.')
          api.setOpen(true)
        })(),
      collapse: () => api.setOpen(false),
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    {...attributes(api.getRootProps())}
    class={styles.card}
    data-status={status}
    aria-busy={(running) ? true : undefined}
    data-member="tool-call"
    ><button
      bind:this={trigger}
      {...attributes(api.getTriggerProps())}
      class={styles.trigger}
      disabled={!hasBody}
      ><span class={styles.mark}><Icon name={icon} size="sm" /></span
      ><span class={styles.name}>{name}</span
      >{#if summary !== undefined}<span class={styles.summary}>{summary}</span>{/if
      }<span class={styles.trailing}
        >{#if duration !== undefined}<span class={styles.duration}>{duration}</span>{/if
        }<span class={[styles.status, running ? styles.spinning : undefined]}
          ><Icon name={statusIcon} size="sm"
        /></span
        ><span class={styles.reader}>{messages.status[status]}</span
        >{#if hasBody}<span class={styles.chevron}><Icon name="down" size="sm" /></span>{/if
      }</span
    ></button
    >{#if hasBody
      }<div
        {...attributes(api.getContentProps())}
        class={styles.content}
        style:--radix-collapsible-content-height={Object(api.getContentProps().style)['--height']}
        ><div class={styles.inner}
          >{#if input !== undefined
            }<div class={styles.section}
              ><span class={styles.heading}>{messages.input}</span
              >{#if typeof input === 'string'
                }<CodeBlock label={messages.input}>{input}</CodeBlock
              >{:else
                }<JsonTree data={input} label={messages.input} defaultDepth={1}
              />{/if
            }</div
          >{/if
          }{#if slots.output
            }<div class={styles.section}
              ><span class={styles.heading}>{messages.output}</span
              >{@render output?.()
            }</div
          >{/if
          }{#if message !== undefined}<p class={styles.message}>{message}</p>{/if
        }</div
      ></div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
